// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, address actor) public {
        // No membership was ever granted for this (role, actor) pair through the
        // public surface: nothing in setUp grants roles to arbitrary fuzzed
        // accounts, so in the correct contract hasRole must return false.
        // The mutant negates the stored flag and returns true here.
        assertTrue(!c.hasRole(role, actor));
    }
}
